#include <iostream>
using namespace std;
class Buf {
public:
    int *p;
    Buf(int v) : p(new int(v)) {}
    Buf(const Buf &o) : p(new int(*o.p)) { cout << "copy "; }
    Buf &operator=(const Buf &o) { *p = *o.p; cout << "assign "; return *this; }
    ~Buf() { delete p; }
};
int main() {
    Buf a(1); Buf b = a; Buf c(9); c = a;
    *a.p = 5;
    cout << *a.p << *b.p << *c.p;
}

